import "core-js/modules/es6.regexp.replace";
import "core-js/modules/es6.regexp.constructor";
import "core-js/modules/es6.array.find";
import "core-js/modules/web.dom.iterable";
import { getList as _getList, userList, addUser } from "@/api/safeDanger/claimExpertPool";
export default {
  name: "userTable",
  props: ['type'],
  data: function data() {
    return {
      loading: false,
      tableList: [],
      tableHeight: null,
      queryParams: {
        current: 1,
        size: 20
      },
      // 总条数
      total: 0
    };
  },
  mounted: function mounted() {
    this.getCurrentHeight();
    this.getList();
  },
  methods: {
    getList: function getList() {
      var _this = this;
      this.loading = true;
      if (this.type == 'add' || this.type == 'edit') {
        _getList({
          current: 1,
          size: 999
        }).then(function (all) {
          userList(_this.queryParams).then(function (res) {
            if (all.data.records && res.data.records) {
              res.data.records.forEach(function (item) {
                if (all.data.records.find(function (a) {
                  return a.userId == item.id;
                })) {
                  item.hasAdd = 1;
                }
              });
            }
            _this.tableList = res.data.records;
            _this.total = res.data.total;
          }).finally(function () {
            _this.loading = false;
          });
        }).catch(function () {
          _this.loading = false;
        });
      } else if (this.type == 'todo') {
        _getList(this.queryParams).then(function (res) {
          _this.tableList = res.rows;
          _this.total = res.total;
        }).finally(function () {
          _this.loading = false;
        });
      }
    },
    handleSel: function handleSel(row) {
      var _this2 = this;
      if (this.type == 'add') {
        addUser({
          userId: row.id
        }).then(function (res) {
          _this2.msgSuccess("新增成功");
          _this2.$emit('closeDialog');
        });
      } else if (this.type == 'edit') {
        this.$emit('editCallback', row);
      } else if (this.type == 'todo') {
        //来自待处理页面指派按钮功能
        this.$emit('editCallback', row);
      }
    },
    Nindex: function Nindex(index) {
      return index + 1 + (this.queryParams.current - 1) * this.queryParams.size;
    },
    // 获取自适应高度
    getCurrentHeight: function getCurrentHeight() {
      var windowHeight = window.innerHeight; //窗口高度
      this.tableHeight = windowHeight - 405 + 'px';
    },
    heightLighText: function heightLighText(row) {
      if (row.realName && this.queryParams.realName) {
        var mgText = this.queryParams.realName;
        var reg = new RegExp(mgText, 'gi');
        var newStr = row.realName.replace(reg, function (matchedText) {
          return "<span style=\"color:#00A9B8;font-weight: bold;\">".concat(matchedText, "</span>");
        });
        return newStr;
      } else {
        return row.realName;
      }
    }
  }
};
